-- Warehouse Inventory dataset (generated by scripts/build_datasets.py; do not edit by hand)
DROP TABLE IF EXISTS stock_movements CASCADE;
DROP TABLE IF EXISTS purchase_orders CASCADE;
DROP TABLE IF EXISTS stock_levels CASCADE;
DROP TABLE IF EXISTS products CASCADE;
DROP TABLE IF EXISTS categories CASCADE;
DROP TABLE IF EXISTS suppliers CASCADE;
DROP TABLE IF EXISTS warehouses CASCADE;

CREATE TABLE warehouses (
  warehouse_id INTEGER PRIMARY KEY,
  name VARCHAR(60) NOT NULL,
  city VARCHAR(60) NOT NULL,
  capacity_units INTEGER NOT NULL CHECK (capacity_units > 0),
  is_active BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE suppliers (
  supplier_id INTEGER PRIMARY KEY,
  supplier_name VARCHAR(80) NOT NULL,
  country VARCHAR(40) NOT NULL,
  contact_email VARCHAR(120),
  rating SMALLINT CHECK (rating BETWEEN 1 AND 5)
);

CREATE TABLE categories (
  category_id INTEGER PRIMARY KEY,
  name VARCHAR(60) NOT NULL,
  parent_id INTEGER REFERENCES categories(category_id)
);

CREATE TABLE products (
  product_id INTEGER PRIMARY KEY,
  sku VARCHAR(20) NOT NULL UNIQUE,
  product_name VARCHAR(80) NOT NULL,
  category_id INTEGER REFERENCES categories(category_id),
  supplier_id INTEGER REFERENCES suppliers(supplier_id),
  unit_cost NUMERIC(10,2) NOT NULL CHECK (unit_cost >= 0),
  reorder_level INTEGER NOT NULL DEFAULT 0 CHECK (reorder_level >= 0),
  is_discontinued BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE TABLE stock_levels (
  warehouse_id INTEGER NOT NULL REFERENCES warehouses(warehouse_id),
  product_id INTEGER NOT NULL REFERENCES products(product_id),
  quantity_on_hand INTEGER NOT NULL CHECK (quantity_on_hand >= 0),
  last_counted DATE,
  PRIMARY KEY (warehouse_id, product_id)
);

CREATE TABLE purchase_orders (
  po_id INTEGER PRIMARY KEY,
  supplier_id INTEGER NOT NULL REFERENCES suppliers(supplier_id),
  warehouse_id INTEGER NOT NULL REFERENCES warehouses(warehouse_id),
  product_id INTEGER NOT NULL REFERENCES products(product_id),
  quantity INTEGER NOT NULL CHECK (quantity > 0),
  unit_cost NUMERIC(10,2) NOT NULL CHECK (unit_cost >= 0),
  order_date DATE NOT NULL,
  expected_date DATE,
  received_date DATE,
  status VARCHAR(10) NOT NULL CHECK (status IN ('draft','ordered','received','cancelled')),
  CHECK (received_date IS NULL OR received_date >= order_date)
);

CREATE TABLE stock_movements (
  movement_id INTEGER PRIMARY KEY,
  warehouse_id INTEGER NOT NULL REFERENCES warehouses(warehouse_id),
  product_id INTEGER NOT NULL REFERENCES products(product_id),
  movement_type VARCHAR(12) NOT NULL CHECK (movement_type IN ('receipt','shipment','transfer','adjustment')),
  quantity INTEGER NOT NULL CHECK (quantity <> 0),
  moved_at TIMESTAMP NOT NULL,
  po_id INTEGER REFERENCES purchase_orders(po_id),
  note VARCHAR(120)
);

















